mapper.body:
{
  "model": "anthropic/claude-sonnet-4-6",
  "models": ["anthropic/claude-sonnet-4-6", "{{env.OPENROUTER_FALLBACK_MODEL}}"],
  "route": "fallback",
  "provider": { "allow_fallbacks": true },
  "messages": [
    {
      "role": "system",
      "content": "You are a calm, professional AI assistant handling an emergency service inquiry. Write a short acknowledgement message (2–3 sentences, no markdown) for a Freshchat chat window. You must: (1) address the customer by first name, (2) acknowledge the urgency without repeating their exact words, (3) assure them a team member will call them back within 15 minutes, (4) ask them to keep their phone nearby. Keep it warm but brief."
    },
    {
      "role": "user",
      "content": "Customer first name: {{1.body.actors[0].first_name}}. Their message: {{1.body.messages[0].text}}"
    }
  ],
  "temperature": 0.3,
  "max_tokens": 200
}

{
  "actor_type": "agent",
  "actor_id": "{{env.FRESHCHAT_BOT_ID}}",
  "message_type": "normal",
  "message_parts": [
    {
      "text": {
        "content": "Hi {{1.body.actors[0].first_name}}, we've received your urgent message and a team member will call you back within 15 minutes. Please keep your phone nearby."
      }
    }
  ]
}

{
  "properties": {
    "dealname": "EMERGENCY — {{1.body.actors[0].first_name}} {{1.body.actors[0].last_name}} {{formatDate(now; \"YYYY-MM-DD HH:mm\"; \"America/New_York\")}}",
    "pipeline": "default",
    "dealstage": "{{env.HUBSPOT_STAGE_NEW_LEAD}}",
    "priority": "HIGH",
    "hs_lead_status": "NEW",
    "description": "Emergency inbound via Freshchat.\nMessage: {{1.body.messages[0].text}}\nContact: {{1.body.actors[0].first_name}} {{1.body.actors[0].last_name}}\nEmail: {{1.body.actors[0].email}}\nPhone: {{1.body.actors[0].phone}}\nConversation ID: {{1.body.id}}\nReceived: {{formatDate(now; \"YYYY-MM-DD HH:mm:ss\"; \"America/New_York\")}} ET\nTag: Emergency",
    "hs_deal_stage_probability": "0"
  }
}

{
  "properties": {
    "hs_timestamp": "{{now}}",
    "hs_note_body": "Emergency callback triggered (Scenario AO).\nFreshchat Conversation ID: {{1.body.id}}\nMessage: {{1.body.messages[0].text}}\nCallback promised within 15 minutes at {{formatDate(now; \"h:mm A\"; \"America/New_York\")}} ET.\nAI acknowledgement sent via Freshchat. HubSpot deal created (ID: {{5.data.id}}).\nInternal alert emailed to brian@cwiai.net."
  },
  "associations": [
    {
      "to": { "id": "{{5.data.id}}" },
      "types": [
        {
          "associationCategory": "HUBSPOT_DEFINED",
          "associationTypeId": 214
        }
      ]
    }
  ]
}
